import{_ as a,o as l,c as i,a0 as o}from"./chunks/framework.D2qex3w9.js";const h=JSON.parse('{"title":"Delta for dynamic-column-config","description":"","frontmatter":{},"headers":[],"relativePath":"changes/archive/2026-06-05-detail-column-support/specs/dynamic-column-config/spec.md","filePath":"changes/archive/2026-06-05-detail-column-support/specs/dynamic-column-config/spec.md"}'),c={name:"changes/archive/2026-06-05-detail-column-support/specs/dynamic-column-config/spec.md"};function t(d,e,n,r,s,u){return l(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="delta-for-dynamic-column-config" tabindex="-1">Delta for dynamic-column-config <a class="header-anchor" href="#delta-for-dynamic-column-config" aria-label="Permalink to &quot;Delta for dynamic-column-config&quot;">​</a></h1><h2 id="added-requirements" tabindex="-1">ADDED Requirements <a class="header-anchor" href="#added-requirements" aria-label="Permalink to &quot;ADDED Requirements&quot;">​</a></h2><h3 id="requirement-detail-property" tabindex="-1">Requirement: Detail Property <a class="header-anchor" href="#requirement-detail-property" aria-label="Permalink to &quot;Requirement: Detail Property&quot;">​</a></h3><p>Columns MAY specify <code>detail: boolean</code> to mark them as carriers of invisible data. A column with <code>detail: true</code> MUST have its row value preserved for emission on cell click, even when <code>visible: false</code>.</p><h4 id="scenario-detail-column-carries-invisible-data-on-click" tabindex="-1">Scenario: Detail column carries invisible data on click <a class="header-anchor" href="#scenario-detail-column-carries-invisible-data-on-click" aria-label="Permalink to &quot;Scenario: Detail column carries invisible data on click&quot;">​</a></h4><ul><li>GIVEN a column <code>{key: &#39;id&#39;, header: &#39;ID&#39;, visible: false, detail: true}</code> and a row <code>{name: &#39;Alice&#39;, id: &#39;42&#39;}</code></li><li>WHEN a clickable cell in that row is clicked</li><li>THEN the <code>cellClick</code> payload includes <code>{label: &#39;ID&#39;, value: &#39;42&#39;}</code> in <code>detailData</code></li></ul><h4 id="scenario-non-detail-invisible-column-excluded-from-emission" tabindex="-1">Scenario: Non-detail invisible column excluded from emission <a class="header-anchor" href="#scenario-non-detail-invisible-column-excluded-from-emission" aria-label="Permalink to &quot;Scenario: Non-detail invisible column excluded from emission&quot;">​</a></h4><ul><li>GIVEN a column <code>{key: &#39;secret&#39;, header: &#39;Secret&#39;, visible: false}</code> without <code>detail: true</code></li><li>WHEN a clickable cell in that row is clicked</li><li>THEN <code>secret</code> MUST NOT appear in <code>detailData</code></li></ul><h3 id="requirement-detail-data-emission" tabindex="-1">Requirement: Detail Data Emission <a class="header-anchor" href="#requirement-detail-data-emission" aria-label="Permalink to &quot;Requirement: Detail Data Emission&quot;">​</a></h3><p>When a <code>clickeable</code> cell is clicked, the component MUST collect all columns where <code>detail: true</code> from that row and append them as <code>detailData</code> in the <code>cellClick</code> payload.</p><h4 id="scenario-multiple-detail-columns-emit-all-values" tabindex="-1">Scenario: Multiple detail columns emit all values <a class="header-anchor" href="#scenario-multiple-detail-columns-emit-all-values" aria-label="Permalink to &quot;Scenario: Multiple detail columns emit all values&quot;">​</a></h4><ul><li>GIVEN columns with <code>key: &#39;orderId&#39;, detail: true</code> and <code>key: &#39;market&#39;, detail: true</code></li><li>AND a row <code>{name: &#39;Alice&#39;, orderId: &#39;ORD-123&#39;, market: &#39;NYSE&#39;}</code></li><li>WHEN the user clicks a clickable cell in that row</li><li>THEN <code>detailData</code> contains two entries with labels &quot;Order ID&quot; and &quot;Market&quot;</li></ul><h4 id="scenario-no-detail-columns-emits-empty-array" tabindex="-1">Scenario: No detail columns emits empty array <a class="header-anchor" href="#scenario-no-detail-columns-emits-empty-array" aria-label="Permalink to &quot;Scenario: No detail columns emits empty array&quot;">​</a></h4><ul><li>GIVEN columns without any <code>detail: true</code></li><li>WHEN a clickable cell is clicked</li><li>THEN <code>cellClick.detailData</code> is <code>[]</code></li></ul><h3 id="requirement-detail-data-format" tabindex="-1">Requirement: Detail Data Format <a class="header-anchor" href="#requirement-detail-data-format" aria-label="Permalink to &quot;Requirement: Detail Data Format&quot;">​</a></h3><p>The <code>detailData</code> field SHOULD be an array of <code>{label: string; value: any}</code> objects. <code>label</code> MUST match the column <code>header</code> and <code>value</code> MUST match the row field value.</p><h4 id="scenario-detaildata-follows-label-value-contract" tabindex="-1">Scenario: detailData follows label/value contract <a class="header-anchor" href="#scenario-detaildata-follows-label-value-contract" aria-label="Permalink to &quot;Scenario: detailData follows label/value contract&quot;">​</a></h4><ul><li>GIVEN a column <code>{key: &#39;code&#39;, header: &#39;Code&#39;, detail: true}</code> and a row with <code>code: &#39;ABC&#39;</code></li><li>WHEN a clickable cell is clicked</li><li>THEN <code>detailData[0]</code> equals <code>{label: &#39;Code&#39;, value: &#39;ABC&#39;}</code></li></ul><h2 id="modified-requirements" tabindex="-1">MODIFIED Requirements <a class="header-anchor" href="#modified-requirements" aria-label="Permalink to &quot;MODIFIED Requirements&quot;">​</a></h2><h3 id="requirement-column-visibility" tabindex="-1">Requirement: Column Visibility <a class="header-anchor" href="#requirement-column-visibility" aria-label="Permalink to &quot;Requirement: Column Visibility&quot;">​</a></h3><p>The table MUST exclude columns with <code>visible: false</code> from the rendered DOM. Columns where <code>visible</code> is <code>undefined</code> or <code>true</code> MUST render normally. Columns with <code>detail: true</code> SHOULD also be <code>visible: false</code> — their data is preserved for emission but not rendered. (Previously: No mention of detail columns or data carriage)</p><h4 id="scenario-column-with-visible-false-is-excluded" tabindex="-1">Scenario: Column with visible: false is excluded <a class="header-anchor" href="#scenario-column-with-visible-false-is-excluded" aria-label="Permalink to &quot;Scenario: Column with visible: false is excluded&quot;">​</a></h4><ul><li>GIVEN a table with columns <code>[{key: &#39;name&#39;, header: &#39;Name&#39;}, {key: &#39;secret&#39;, header: &#39;Secret&#39;, visible: false}]</code></li><li>WHEN the table renders</li><li>THEN only the <code>name</code> column appears in the rendered DOM</li><li>AND the <code>secret</code> column is absent (not merely hidden via CSS)</li></ul><h4 id="scenario-column-with-undefined-visible-renders" tabindex="-1">Scenario: Column with undefined visible renders <a class="header-anchor" href="#scenario-column-with-undefined-visible-renders" aria-label="Permalink to &quot;Scenario: Column with undefined visible renders&quot;">​</a></h4><ul><li>GIVEN a column with no <code>visible</code> property set</li><li>WHEN the table renders</li><li>THEN that column appears in the rendered DOM</li></ul><h3 id="requirement-clickable-cells" tabindex="-1">Requirement: Clickable Cells <a class="header-anchor" href="#requirement-clickable-cells" aria-label="Permalink to &quot;Requirement: Clickable Cells&quot;">​</a></h3><p>When a column has <code>clickeable: true</code>, clicking a cell MUST emit a <code>cellClick</code> event with payload <code>{ column: TableColumn; row: any; detailData?: {label: string, value: any}[] }</code>. The component MUST NOT handle the action itself — it delegates to the parent. When detail columns exist, their values are included in <code>detailData</code>. (Previously: Payload was <code>{ column; row }</code> without detailData)</p><h4 id="scenario-clickable-cell-emits-cellclick-with-detaildata" tabindex="-1">Scenario: Clickable cell emits cellClick with detailData <a class="header-anchor" href="#scenario-clickable-cell-emits-cellclick-with-detaildata" aria-label="Permalink to &quot;Scenario: Clickable cell emits cellClick with detailData&quot;">​</a></h4><ul><li>GIVEN a column <code>{key: &#39;name&#39;, header: &#39;Name&#39;, clickeable: true}</code></li><li>AND a detail column <code>{key: &#39;id&#39;, header: &#39;ID&#39;, visible: false, detail: true}</code></li><li>AND a row <code>{name: &#39;Alice&#39;, id: &#39;42&#39;}</code></li><li>WHEN the user clicks the &quot;Alice&quot; cell</li><li>THEN <code>cellClick</code> payload includes <code>detailData: [{label: &#39;ID&#39;, value: &#39;42&#39;}]</code></li></ul><h4 id="scenario-non-clickable-cell-emits-nothing" tabindex="-1">Scenario: Non-clickable cell emits nothing <a class="header-anchor" href="#scenario-non-clickable-cell-emits-nothing" aria-label="Permalink to &quot;Scenario: Non-clickable cell emits nothing&quot;">​</a></h4><ul><li>GIVEN a column without <code>clickeable</code> or with <code>clickeable: false</code></li><li>WHEN the user clicks a cell in that column</li><li>THEN no <code>cellClick</code> event is emitted</li></ul>',31)])])}const b=a(c,[["render",t]]);export{h as __pageData,b as default};
